{
  "nl": {
    "issue": [
      {
        "text": "当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担何种违约责任",
        "rules": ["c577-1"]
      },
      {
        "text": "履行期限届满前一方明确表示或者以自己的行为表明不履行的，对方能否提前请求其承担违约责任",
        "rules": ["c578-1"]
      },
      {
        "text": "非金钱债务不履行时，对方请求履行受哪些限制；因除外情形致不能实现合同目的时，合同关系如何处理",
        "rules": ["c580-1", "c580-2", "c580-2b"]
      },
      {
        "text": "违约损失赔偿的范围、可得利益与可预见性限制",
        "rules": ["c583-1", "c584-1", "c584-2"]
      }
    ],
    "conditions": [
      {
        "text": "当事人之间存在有效合同（笔记列为违约责任构成要件之一）",
        "rules": ["c577-valid"]
      },
      {
        "text": "客观上有违约行为：不履行（实际不履行、预期违约）或者不适当履行",
        "rules": ["c577-actual", "c577-improper", "c577-anticipatory"]
      },
      {
        "text": "不履行的是非金钱债务，或者履行非金钱债务不符合约定",
        "rules": ["c580-1"]
      },
      {
        "text": "违约行为造成对方损失",
        "rules": ["c584-1"]
      },
      {
        "text": "在履行义务或者采取补救措施后，对方还有其他损失",
        "rules": ["c583-1"]
      },
      {
        "text": "有第580条第1款除外情形之一，致使不能实现合同目的，且当事人提出请求",
        "rules": ["c580-2"]
      }
    ],
    "exceptions": [
      {
        "text": "法律上或者事实上不能履行；债务的标的不适于强制履行或者履行费用过高；债权人在合理期限内未请求履行（第580条第1款但书）",
        "rules": ["c580-1"]
      },
      {
        "text": "赔偿额不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失",
        "rules": ["c584-2"]
      },
      {
        "text": "不存在免责事由（笔记列为构成要件之三）；存在法定或约定免责事由的，不承担违约责任",
        "rules": ["c577-exempt"]
      }
    ],
    "effects": [
      {
        "text": "违约方应当承担继续履行、采取补救措施或者赔偿损失等违约责任",
        "rules": ["c577-1"]
      },
      {
        "text": "对方可以在履行期限届满前请求其承担违约责任",
        "rules": ["c578-1"]
      },
      {
        "text": "对方可以请求履行该非金钱债务",
        "rules": ["c580-1"]
      },
      {
        "text": "人民法院或者仲裁机构可以根据当事人的请求终止合同权利义务关系，但不影响违约责任的承担",
        "rules": ["c580-2", "c580-2b"]
      },
      {
        "text": "履行义务或者采取补救措施后对方还有其他损失的，应当赔偿损失",
        "rules": ["c583-1"]
      },
      {
        "text": "损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益",
        "rules": ["c584-1"]
      }
    ],
    "priority": [
      {
        "text": "可预见性规则优先，限制第584条前段的完全赔偿范围",
        "rules": ["c584-2", "c584-1"]
      },
      {
        "text": "预期违约情形下第578条作为特别规定优先适用，可在履行期限届满前追责",
        "rules": ["c578-1", "c577-1"]
      },
      {
        "text": "存在免责事由时排除第577条的违约责任",
        "rules": ["c577-exempt", "c577-1"]
      }
    ],
    "distinguish": [
      {
        "text": "第578条针对履行期限届满前的预期违约（明确表示或以行为表明不履行），第577条针对实际不履行与不适当履行；笔记将预期违约亦归入“不履行”",
        "rules": ["c578-1", "c577-actual", "c577-anticipatory"]
      },
      {
        "text": "第580条限于非金钱债务的履行请求并列举三项除外情形；金钱债务的支付请求权（第579条）本行未挂载，不写规则",
        "rules": ["c580-1"]
      },
      {
        "text": "第583条处理采取补救措施后仍存在的其他损失，第584条处理损失赔偿的范围与可预见性限制，二者层次不同",
        "rules": ["c583-1", "c584-1"]
      },
      {
        "text": "LEGO 卡片提到的债务免除（第575条）、债权债务混同（第576条）属合同权利义务终止，本行未挂载，不写规则",
        "rules": []
      }
    ]
  },
  "rules": [
    {
      "key": "c577-valid",
      "srcs": ["art577"],
      "body": ["contractAgreement(K)", "valid(K)"],
      "heads": ["contractInForce(K)"],
      "note": "笔记将“当事人之间存在有效合同”列为违约责任构成要件；合同有效成立方发生违约责任（学理，非第577条明文）",
      "auth": "doctrine"
    },
    {
      "key": "c577-1",
      "srcs": ["art577"],
      "body": [
        "contractInForce(K)",
        "partyToDebtRelation(P,K)",
        "partyToDebtRelation(O,K)",
        {"or": ["nonPerformance(P,K)", "performanceNotConforming(P,K)"]}
      ],
      "heads": [
        {"type": "OBL", "bearer": "P", "counterparty": "O", "content": "liableForBreach(P,K)"}
      ],
      "note": "一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任",
      "auth": "npc"
    },
    {
      "key": "c577-actual",
      "srcs": ["art577"],
      "body": ["contractInForce(K)", "partyToDebtRelation(P,K)", "performancePeriodExpired(K)", "~performed(P,K)"],
      "heads": ["nonPerformance(P,K)"],
      "note": "笔记：实际不履行指履行期限届满之时仍未履行",
      "auth": "doctrine"
    },
    {
      "key": "c577-improper",
      "srcs": ["art577"],
      "body": ["contractInForce(K)", "partyToDebtRelation(P,K)", "performed(P,K)", "~performanceConforms(P,K)"],
      "heads": ["performanceNotConforming(P,K)"],
      "note": "笔记：不适当履行指虽有履行行为但履行不符合合同要求",
      "auth": "doctrine"
    },
    {
      "key": "c577-anticipatory",
      "srcs": ["art577", "art578"],
      "body": [
        "contractInForce(K)",
        "partyToDebtRelation(P,K)",
        {"or": ["expresslyRefusesPerformance(P,K)", "indicatesByConductNonPerformance(P,K)"]}
      ],
      "heads": ["nonPerformance(P,K)"],
      "note": "笔记：预期违约（履行期届满前明确表示或以行为表明不履行）亦属违约行为之“不履行”",
      "auth": "doctrine"
    },
    {
      "key": "c577-exempt",
      "srcs": ["art577"],
      "body": ["exemptFromBreachLiability(P,K)"],
      "heads": ["-liableForBreach(P,K)"],
      "note": "笔记将“不存在免责事由”列为构成要件之三；存在法定或约定免责事由的，不承担违约责任（本行未挂载第590条，仅作学理提示）",
      "auth": "doctrine"
    },
    {
      "key": "c578-1",
      "srcs": ["art578"],
      "body": [
        "contractInForce(K)",
        "partyToDebtRelation(P,K)",
        "partyToDebtRelation(O,K)",
        {"or": ["expresslyRefusesPerformance(P,K)", "indicatesByConductNonPerformance(P,K)"]}
