      "heads": [
        {"type": "PERM", "bearer": "O", "counterparty": "P", "content": "claimBreachLiabilityBeforeDue(O,P,K)"}
      ],
      "note": "一方明确表示或者以自己的行为表明不履行合同义务的，对方可以在履行期限届满前请求其承担违约责任",
      "auth": "npc"
    },
    {
      "key": "c580-1",
      "srcs": ["art580-1"],
      "body": [
        "contractInForce(K)",
        "partyToDebtRelation(P,K)",
        "partyToDebtRelation(O,K)",
        "nonMonetaryDebt(P,K)",
