      ],
      "heads": [
        {"type": "OBL", "bearer": "P", "counterparty": "O", "content": "limitCompensationToForeseeableLoss(P,K)"}
      ],
      "note": "赔偿额不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失",
      "auth": "npc"
    }
  ],
